import React, { useState } from 'react';
import './App.css'; 

function App() {
  const [pantalla, setPantalla] = useState('formulario');
  const [productos, setProductos] = useState([]);

  // Estados de los campos del formulario
  const [nombre, setNombre] = useState('Empanada');
  const [categoria, setCategoria] = useState('Fritos');
  const [imagenUrl, setImagenUrl] = useState('https://www.bing.com/images/search?view=detailV2&ccid=PKW%2Ff');
  const [precioCosto, setPrecioCosto] = useState(1500);
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState(2400);
  const [stock, setStock] = useState(20);

  const porcentajeIVA = parseFloat(impuesto) / 100;
  const costoConIVA = precioCosto * (1 + porcentajeIVA);
  const margenSugerido = costoConIVA * 1.30;

  const formatearMoneda = (valor) => {
    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0
    }).format(valor);
  };

  // Traer inventario desde Spring Boot
  const cargarInventario = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
        setPantalla('inventario');
      } else {
        alert("Error al leer los productos del backend.");
      }
    } catch (error) {
      alert("No se pudo conectar con Java. ¿Olvidaste encender el backend?");
    }
  };

  // Guardar producto en el_paisita_up
  const handleGuardar = async (e) => {
    e.preventDefault();

    // Nombres mapeados exactamente para la Entidad de Java
    const nuevoProducto = {
      nombre: nombre,
      categoria: categoria,
      imagenUrl: imagenUrl,
      precioCosto: parseFloat(precioCosto),
      impuesto: parseFloat(impuesto),
      precioVenta: parseFloat(precioVenta),
      stock: parseInt(stock)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });

      if (respuesta.ok) {
        alert("¡Producto guardado con éxito en El Paisita UP!");
        cargarInventario(); // Te lleva directo a ver el inventario actualizado
      } else {
        alert("Java rechazó el registro. Revisa que las variables en Producto.java coincidan con el JSON.");
      }
    } catch (error) {
      alert("Error crítico de conexión.");
    }
  };

  return (
    <div>
      <div className="nav-container">
        {pantalla === 'formulario' ? (
          <button className="btn-nav-inventario" onClick={cargarInventario}>📦 Ver Inventario</button>
        ) : (
          <button className="btn-nav-inventario" onClick={() => setPantalla('formulario')}>➕ Agregar Producto</button>
        )}
        <button className="btn-nav-salir" onClick={() => alert("Sesión terminada")}>🚪 Salir</button>
      </div>

      {pantalla === 'formulario' && (
        <div className="form-card">
          <h2 className="form-title">Ingreso de Mercancía <span>(distribuidor)</span></h2>
          <form onSubmit={handleGuardar}>
            <div className="form-group">
              <label className="form-label">Nombre del Producto</label>
              <input type="text" value={nombre} onChange={(e) => setNombre(e.target.value)} className="form-input" />
            </div>
            <div className="form-group">
              <label className="form-label">Categoría</label>
              <input type="text" value={categoria} onChange={(e) => setCategoria(e.target.value)} className="form-input" />
            </div>
            <div className="form-group">
              <label className="form-label">Imagen (URL)</label>
              <input type="text" value={imagenUrl} onChange={(e) => setImagenUrl(e.target.value)} className="form-input" />
            </div>
            <div className="form-row">
              <div>
                <label className="form-label">Precio Costo</label>
                <input type="number" value={precioCosto} onChange={(e) => setPrecioCosto(Number(e.target.value))} className="form-input" />
              </div>
              <div>
                <label className="form-label">Impuesto</label>
                <select value={impuesto} onChange={(e) => setImpuesto(e.target.value)} className="form-input">
                  <option value="19">IVA 19% (General CO)</option>
                  <option value="8">INC 8% (Consumo)</option>
                  <option value="0">Exento</option>
                </select>
              </div>
            </div>
            <div className="suggested-box">
              <p className="suggested-title">Costo con IVA + Margen Sugerido (30% Generado)</p>
              <div className="suggested-price">{formatearMoneda(margenSugerido)}</div>
            </div>
            <div className="form-row">
              <div>
                <label className="form-label">Precio Venta</label>
                <input type="number" value={precioVenta} onChange={(e) => setPrecioVenta(Number(e.target.value))} className="form-input" />
              </div>
              <div>
                <label className="form-label">Stock Inicial</label>
                <input type="number" value={stock} onChange={(e) => setStock(Number(e.target.value))} className="form-input" />
              </div>
            </div>
            <button type="submit" className="btn-submit">Meter a la Base de Datos</button>
          </form>
        </div>
      )}

      {pantalla === 'inventario' && (
        <div className="form-card" style={{ maxWidth: '750px' }}>
          <h2 className="form-title">Inventario Actual <span>Cafetería El Paisita</span></h2>
          {productos.length === 0 ? (
            <p style={{ textAlign: 'center', color: '#9C8473' }}>No hay registros en la base de datos.</p>
          ) : (
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ borderBottom: '1px solid #4E3D32', textAlign: 'left' }}>
                    <th style={{ padding: '12px', fontSize: '11px', color: '#9C8473', textTransform: 'uppercase' }}>Producto</th>
                    <th style={{ padding: '12px', fontSize: '11px', color: '#9C8473', textTransform: 'uppercase' }}>Categoría</th>
                    <th style={{ padding: '12px', fontSize: '11px', color: '#9C8473', textTransform: 'uppercase' }}>Costo</th>
                    <th style={{ padding: '12px', fontSize: '11px', color: '#9C8473', textTransform: 'uppercase' }}>Venta</th>
                    <th style={{ padding: '12px', fontSize: '11px', color: '#9C8473', textTransform: 'uppercase' }}>Stock</th>
                  </tr>
                </thead>
                <tbody>
                  {productos.map((p, i) => (
                    <tr key={i} style={{ borderBottom: '1px solid #2D1F16', fontSize: '14px' }}>
                      <td style={{ padding: '12px', color: '#F5F5F5', fontWeight: '500' }}>{p.nombre}</td>
                      <td style={{ padding: '12px', color: '#E3CBB3' }}>{p.categoria}</td>
                      <td style={{ padding: '12px', color: '#9C8473' }}>{formatearMoneda(p.precioCosto)}</td>
                      <td style={{ padding: '12px', color: '#C1D7C3', fontWeight: '600' }}>{formatearMoneda(p.precioVenta)}</td>
                      <td style={{ padding: '12px', color: p.stock < 5 ? '#E8C5C8' : '#F5F5F5' }}>{p.stock} uds</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
